def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    my_def = 0
    for m, o in history:
        if o == 'D':
            opp_def += 1
        if m == 'D':
            my_def += 1

    last_m, last_o = history[-1]

    if n < 10:
        if last_o == 'D':
            return 'D'
        return 'C'

    if n > 90:
        if opp_def <= 2:
            return 'C'

    if last_o == 'C':
        return 'C'

    if n < 30:
        if opp_def <= max(1, n // 10):
            return 'C'
        if n >= 2 and last_m == 'C' and history[-2][0] == 'D':
            return 'C'
        if n >= 2 and last_m == 'D' and history[-2][1] == 'D':
            if my_def <= 1 and opp_def <= n * 0.5:
                return 'C'
        return 'D'

    if opp_def > n * 0.3:
        return 'D'
    if opp_def > n * 0.15:
        if last_m == 'D' and last_o == 'D':
            if n >= 2 and history[-2][1] == 'D':
                return 'C'
        return 'D'
    return 'C'
